<p id="leaderboardUpdateStatus" role="status" class="mt-4 text-xs text-secondary">Updates automatically every 30 seconds.</p>
<script>
let rankingRefreshPending=false;
setInterval(async()=>{
    if(document.hidden || rankingRefreshPending || document.querySelector('#leaderboardContent form')?.contains(document.activeElement)) return;
    rankingRefreshPending=true;
    const status=document.getElementById('leaderboardUpdateStatus');
    try {
        const response=await fetch(location.href,{headers:{Accept:'text/html'}});
        if(!response.ok) throw new Error();
        const documentCopy=new DOMParser().parseFromString(await response.text(),'text/html');
        const updated=documentCopy.getElementById('leaderboardContent');
        if(!updated) {status.textContent='Sign in again to refresh rankings.';return;}
        document.getElementById('leaderboardContent').replaceWith(updated);
        status.textContent='Rankings updated. Refreshes every 30 seconds.';
    } catch(error) {status.textContent='Unable to refresh rankings. Your last loaded results are shown.';}
    finally {rankingRefreshPending=false;}
},30000);
</script>
